def pick_addr(url, cc=None, rc=None):
    cc = (cc or "").upper()
    rc = (rc or "").upper()
    dom = urlparse(url).netloc
    tcn = dom.split('.')[-1].upper()
    def _pick(entries):
        return random.choice(entries) if isinstance(entries, list) else entries
    if tcn in book:
        return _pick(book[tcn])
    ccn = C2C.get(cc)
    if rc in book and ccn == rc:
        return _pick(book[rc])
    elif rc in book:
        return _pick(book[rc])
    return _pick(book["DEFAULT"])

def extract_between(text, start, end):
    if not text or not start or not end:
        return None
    try:
        if start in text:
            parts = text.split(start, 1)
            if len(parts) > 1 and end in parts[1]:
                return parts[1].split(end, 1)[0]
        return None
    except Exception:
        return None

